schema_ddl:
CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR(255),
    FOLLOWER VARCHAR(255),
    PRIMARY KEY (FOLLOWEE, FOLLOWER),
    CHECK (FOLLOWEE <> FOLLOWER)
);

counterexample:
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Bob', 'Alice');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Alice', 'Bob');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Charlie', 'Bob');

